// CUA-only UI orchestration. Imported by the task's cua_repl session; no browser
// connection, app injection, network or filesystem operations are performed.
export function createQa() {
  return {
    async chat(p) {
      return p.tab.playwright.locator(p.log).evaluate(e => {
        const rows = [...e.querySelectorAll('.guide-assistant-message')], last = rows.at(-1);
        return {count: rows.length, user: rows.at(-2)?.querySelector('.ga-msg-text')?.textContent,
          decision: last?.dataset.decision, rendered: last?.querySelector('.ga-msg-text')?.innerText};
      }, null, {timeoutMs: 15000});
    },
    async input(p) { return p.tab.playwright.locator(p.input).evaluate(e => e.value, null, {timeoutMs: 15000}); },
    async clear(p) {
      try { await p.tab.playwright.getByRole('button', {name: 'Clear chat', exact: true}).click({timeoutMs: 10000}); }
      catch (e) { if ((await this.chat(p)).count) throw e; }
    },
    async read(p, q) {
      const end = Date.now() + 25000;
      while (Date.now() < end) {
        try {
          const actual = await this.chat(p);
          if (actual.user === q && actual.decision && actual.decision !== 'pending'
            && await p.tab.playwright.locator(p.button).isEnabled()) return actual;
        } catch (e) { if (!/timed out|deadline/i.test(String(e))) throw e; }
      }
      throw Error('Matching UI turn unfinished');
    },
    async ask(p, q) {
      await p.tab.playwright.locator(p.input).fill(q, {timeoutMs: 15000});
      try { await p.tab.playwright.locator(p.button).click({timeoutMs: 10000}); }
      catch (e) {
        const value = await this.input(p), actual = await this.chat(p);
        if (value === q && await p.tab.playwright.locator(p.button).isEnabled())
          await p.tab.playwright.locator(p.button).press('Enter', {timeoutMs: 15000});
        else if (value !== '' || actual.user !== q) throw e;
      }
      return this.read(p, q);
    },
    advance(p) {
      p.state.t++; p.state.done++;
      if (p.state.t === p.state.dialogues[p.state.d].turns.length) { p.state.t = 0; p.state.d++; }
      p.pending = null;
    },
    async window(p) {
      const start = Date.now(), s = p.state; let count = 0, last;
      try {
        while (s.d < s.dialogues.length && count < 20) {
          const d = s.dialogues[s.d], q = d.turns[s.t].text;
          if (!p.pending) {
            if (s.t === 0) await this.clear(p);
            p.pending = {d: s.d, t: s.t, q};
            last = await this.ask(p, q);
          } else {
            if (p.pending.d !== s.d || p.pending.t !== s.t || p.pending.q !== q) throw Error('Pending replay index mismatch');
            const actual = await this.chat(p), value = await this.input(p);
            last = actual.user === q && value === '' ? await this.read(p, q) : await this.ask(p, q);
          }
          this.advance(p); count++;
          if (Date.now() - start > 12000) break;
        }
      } catch (e) {
        if (!/timed out|deadline|unfinished/i.test(String(e))) throw e;
        return {dataset:p.dataset,done:s.done,d:s.d,t:s.t,pending:p.pending?.q,error:String(e)};
      }
      return {dataset:p.dataset,done:s.done,d:s.d,t:s.t,remaining:s.dialogues.length-s.d,last:last?.decision};
    },
    async loadSuite(p, id, dataset) {
      const raw = JSON.parse(await p.tab.playwright.locator('#'+id).textContent());
      const ds = (Array.isArray(raw) ? raw : raw.dialogues)
        .filter(d => (d.gameId || raw.gameId || p.game) === p.game && (!d.surface || d.surface === p.surface));
      p.dataset = dataset; p.pending = null; p.state = {dialogues:ds,d:0,t:0,done:0};
      return {dataset,dialogues:ds.length,turns:ds.reduce((n,d)=>n+d.turns.length,0)};
    },
    async block(p, emit = () => {}, budgetMs = 25000) {
      const start = Date.now();
      for (let n=0;n<8;n++) {
        emit(await this.window(p));
        if (p.state.d === p.state.dialogues.length) {
          p.completed ??= []; p.completed.push({dataset:p.dataset,turns:p.state.done});
          if (!p.queue?.length) { p.finished=true; break; }
          const next=p.queue.shift(); emit(await this.loadSuite(p,next[0],next[1]));
        }
        if (Date.now()-start > budgetMs) break;
      }
      return {completed:p.completed,current:p.dataset,finished:!!p.finished};
    },
    async export(p) {
      const event=p.tab.playwright.waitForEvent('download',{timeoutMs:30000});
      await p.tab.playwright.getByRole('button',{name:'Export local native probe',exact:true}).click({timeoutMs:15000});
      return (await event).path();
    }
  };
}

// Same CUA browser capability and native keyboard; no other UI framework.
// Runtime.evaluate expressions below only read the visible DOM. All changes
// use documented DOM.focus, Input.insertText and Tab.pressKey UI interactions.
export function createFastQa() {
  const qa=createQa();
  qa.attach=async function(p) {
    p.cdp=await p.tab.capabilities.get('cdp');
    const doc=await p.cdp.send('DOM.getDocument',{depth:0});
    const input=await p.cdp.send('DOM.querySelector',{nodeId:doc.root.nodeId,selector:p.input});
    if(!input.nodeId)throw Error('Visible chat input missing');
    const clear=await p.cdp.send('Runtime.evaluate',{expression:
      `Array.from(document.querySelectorAll('.guide-assistant-controls button')).find(e=>e.title==='Clear every conversation with this guide.'&&e.getClientRects().length>0)`,returnByValue:false});
    if(!clear.result?.objectId)throw Error('Visible Clear chat button missing');
    const clearNode=await p.cdp.send('DOM.requestNode',{objectId:clear.result.objectId});
    p.dom={input:input.nodeId,clear:clearNode.nodeId};
    p.readExpression=`(s=>{const root=document.querySelector(s.log),n=[...root.querySelectorAll('.guide-assistant-message')],last=n.at(-1);return {count:n.length,user:n.at(-2)?.querySelector('.ga-msg-text')?.textContent,decision:last?.dataset.decision,rendered:last?.querySelector('.ga-msg-text')?.textContent,input:document.querySelector(s.input).value,disabled:document.querySelector(s.button).disabled,focused:document.activeElement===document.querySelector(s.input)};})(${JSON.stringify({input:p.input,button:p.button,log:p.log})})`;
  };
  qa.chat=async function(p) {
    if(!p.dom)await this.attach(p);
    const r=await p.cdp.send('Runtime.evaluate',{expression:p.readExpression,returnByValue:true},{timeoutMs:15000});
    if(r.exceptionDetails||!r.result?.value)throw Error('DOM-only chat observation failed');
    return r.result.value;
  };
  qa.input=async function(p) {return (await this.chat(p)).input;};
  qa.read=async function(p,q) {
    if(!p.dom)await this.attach(p);
    const args=JSON.stringify({log:p.log,button:p.button,q});
    const expression=`(s=>new Promise(resolve=>{const root=document.querySelector(s.log),button=document.querySelector(s.button);let observer,timer;const snapshot=()=>${p.readExpression};const cleanup=()=>{observer.disconnect();clearTimeout(timer);};const check=()=>{const a=snapshot();if(a.user===s.q&&a.decision&&a.decision!=='pending'&&!a.disabled&&a.input===''){cleanup();resolve(a);}};observer=new MutationObserver(check);observer.observe(root,{subtree:true,childList:true,characterData:true,attributes:true});observer.observe(button,{attributes:true,attributeFilter:['disabled']});timer=setTimeout(()=>{cleanup();resolve({...snapshot(),observationTimedOut:true});},25000);check();}))(${args})`;
    const r=await p.cdp.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true},{timeoutMs:30000});
    const a=r.result?.value;
    if(r.exceptionDetails||!a||a.observationTimedOut)throw Error('Matching UI turn unfinished');
    return a;
  };
  qa.ask=async function(p,q) {
    const a=await this.chat(p);
    if(a.disabled)throw Error('Previous UI submission unfinished');
    if(a.input!==''&&a.input!==q)throw Error('Unexpected unsubmitted input');
    if(!a.focused)await p.cdp.send('DOM.focus',{nodeId:p.dom.input});
    if(a.input==='')await p.cdp.send('Input.insertText',{text:q});
    try {await p.tab.pressKey(null,'Return');}
    catch(e){const current=await this.chat(p);if(current.user!==q||current.input!=='')throw e;}
    return this.read(p,q);
  };
  qa.clear=async function(p) {
    if(!p.dom)await this.attach(p);
    await p.cdp.send('DOM.focus',{nodeId:p.dom.clear});
    await p.tab.pressKey(null,'Return');
    if((await this.chat(p)).count) {
      await p.tab.playwright.getByRole('button',{name:'Clear chat',exact:true}).click({timeoutMs:15000});
      if((await this.chat(p)).count)throw Error('Clear chat did not take effect');
    }
  };
  return qa;
}

// CUA-only UI63 helper. No browser ownership, filesystem/network calls, app
// internals, DOM writes, or synthetic events. The caller supplies already-open
// browser/tab and createFastQa() objects from cua-goal-runner-20261031.mjs.
// Every visible mutation uses CUA Playwright controls or CDP input commands.
const SURFACES=['albion','ultima5','ultima6','ultima7','alqadim','alqadim-walkthrough','starcraft'];
const VIEWPORTS=[[1280,900],[767,806],[390,844],[767,500],[390,500],[844,390]];
const EXPANSION=[[1280,900],[390,844]];
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const ensure=(condition,message)=>{if(!condition)throw Error(message);};
const equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
export const sourcePresent=(source,citations)=>{
  if(!source?.file||!source?.locator)return false;
  if(/^https?:\/\//i.test(source.file)){
   const escape=value=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
   const pattern=new RegExp('(?:^|: |; )'+escape(source.locator+' — '+source.file)+'(?: \\(checked \\d{4}-\\d{2}-\\d{2}\\))?(?:; |\\.?$)');
   return citations.some(value=>pattern.test(value));
  }
  const tuples=new Set();
  for(const value of citations){
   const index=value.startsWith('Source:')?value.indexOf('. '):-1,body=index>=0?value.slice(index+2):value;
   let file=null;
   for(const part of body.split('; ')){
    let locator=part;const delimiter=part.indexOf(' — ');
    if(delimiter>=0){const candidate=part.slice(0,delimiter).trim();
     if(/^(?:https?:\/\/\S+|[\w./-]+\.[\w]+)$/.test(candidate)){file=candidate;locator=part.slice(delimiter+3);}}
    if(file){const loc=locator.trim();tuples.add(JSON.stringify([file,loc]));tuples.add(JSON.stringify([file,loc.replace(/\.$/,'')]));}
   }
  }
  return source.locator.split('; ').every(locator=>tuples.has(JSON.stringify([source.file,locator.trim()])));
};
const narrow=value=>typeof value==='string'?value.toLocaleLowerCase():'';

// Mirrors the clipped viewport/ancestor geometry in chat-layout-browser.py;
// nothing here calls scrollIntoView or changes scrollTop.
const GEOMETRY=`(selector=>{
 const e=document.querySelector(selector);if(!e)return null;
 const r=e.getBoundingClientRect();let left=Math.max(0,r.left),right=Math.min(innerWidth,r.right),top=Math.max(0,r.top),bottom=Math.min(innerHeight,r.bottom);
 for(let a=e.parentElement;a;a=a.parentElement){if(a===document.body||a===document.documentElement)continue;
  const s=getComputedStyle(a),ar=a.getBoundingClientRect();
  if(['auto','scroll','hidden','clip'].includes(s.overflowY)){top=Math.max(top,ar.top+a.clientTop);bottom=Math.min(bottom,ar.top+a.clientTop+a.clientHeight);}
  if(['auto','scroll','hidden','clip'].includes(s.overflowX)){left=Math.max(left,ar.left+a.clientLeft);right=Math.min(right,ar.left+a.clientLeft+a.clientWidth);}}
 const x=(left+right)/2,y=(top+bottom)/2,hit=right>left&&bottom>top?document.elementFromPoint(x,y):null;
 return {x:r.x,y:r.y,width:r.width,height:r.height,top:r.top,bottom:r.bottom,scrollTop:e.scrollTop,scrollHeight:e.scrollHeight,clientHeight:e.clientHeight,
  visibleWidth:Math.max(0,right-left),visibleHeight:Math.max(0,bottom-top),hitTestable:!!hit&&(hit===e||e.contains(hit)),point:{x,y}};
})`;
const LOG=`(selector=>{const log=document.querySelector(selector);if(!log)return null;const r=log.getBoundingClientRect(),cards=[...log.querySelectorAll('.guide-assistant-message')];
 const describe=e=>{const a=e.getBoundingClientRect();return {top:a.top,bottom:a.bottom,height:a.height,clientHeight:e.clientHeight,scrollHeight:e.scrollHeight,role:e.classList.contains('user')?'user':'assistant'};};
 return {top:r.top+log.clientTop,bottom:r.top+log.clientTop+log.clientHeight,scrollTop:log.scrollTop,clientHeight:log.clientHeight,scrollHeight:log.scrollHeight,count:cards.length,cards:cards.map(describe),first:cards[0]&&describe(cards[0]),last:cards.at(-1)&&describe(cards.at(-1))};})`;
const NO_HELP=`(()=>{const explicit=[...document.querySelectorAll('.sage-spoiler,#seer-spoiler-select,#sc-assistant-spoiler,.ga-level,.ga-level-note,.ga-level-title,.ga-msg-level,[name="spoiler"],[name="help-level"]')];
 const selects=[...document.querySelectorAll('select')].filter(e=>[...e.options].some(o=>['gentle','balanced','direct','light'].includes(o.value)));
 const controls=[...document.querySelectorAll('.guide-assistant-controls [role="radio"],.guide-assistant-controls [role="radiogroup"],.guide-assistant-controls [data-level]')];
 return [...new Set([...explicit,...selects,...controls])].map(e=>({tag:e.tagName,id:e.id,className:e.className,hidden:e.hidden,ariaHidden:e.getAttribute('aria-hidden')}));})()`;
const MODAL=`(()=>{const p=document.querySelector('.u6-seer-modal__panel')?.getBoundingClientRect(),v=document.querySelector('.u6-seer-modal__view')?.getBoundingClientRect();return p&&v?{panelTop:p.top,panelBottom:p.bottom,viewTop:v.top,viewBottom:v.bottom}:null;})()`;
const CONTEXT=`(()=>({u6title:document.querySelector('#seer-modal-title')?.textContent,u6summary:document.querySelector('#seer-modal-summary')?.textContent,u7title:document.querySelector('#ai-modal-title')?.textContent,hash:location.hash}))()`;

export function createUi63({browser,tab,qa,p,pointerScale=1}){
 ensure(browser&&tab&&qa&&p,'browser, tab, qa and p are required');
 p.tab=tab;const rows=[];let layout,viewport,seedTurns=[],seedPending=null;
 async function dom(expression){const r=await p.cdp.send('Runtime.evaluate',{expression,returnByValue:true},{timeoutMs:15000});if(r.exceptionDetails)throw Error('DOM observation failed');return r.result?.value;}
 async function measure(fn,selector){return dom(`${fn}(${JSON.stringify(selector)})`);}
 async function attach(){delete p.dom;await qa.attach(p);}
 async function noHelp(){const controls=await dom(NO_HELP);ensure(Array.isArray(controls)&&controls.length===0,'Help-level selector or badge exists');return controls;}
 async function settled(selector){
  const expression=`(s=>new Promise(resolve=>{let previous,stable=0,frames=0;const tick=()=>{const e=s?document.querySelector(s):document.activeElement,r=e?.getBoundingClientRect(),value=JSON.stringify([r?.x,r?.y,r?.width,r?.height,e?.scrollTop,scrollX,scrollY]);stable=value===previous?stable+1:0;previous=value;frames++;if(frames>5&&stable>=3)return resolve({stable:true,frames});if(frames>=90)return resolve({stable:false,frames});requestAnimationFrame(tick);};requestAnimationFrame(tick);}))(${JSON.stringify(selector)})`;
  const r=await p.cdp.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true},{timeoutMs:10000});ensure(r.result?.value?.stable,'Control geometry did not settle after real focus/wheel scrolling');
 }
 async function scroll(delta,where){let g=await measure(GEOMETRY,p.log);
  for(let n=0;n<3&&g&&(!g.hitTestable||g.visibleHeight===0);n++){
   const height=await dom('innerHeight'),direction=(g.top+g.height/2)<height/2?-240:240;
   await p.cdp.send('Input.dispatchMouseEvent',{type:'mouseWheel',x:1/pointerScale,y:(height/2)/pointerScale,deltaX:0,deltaY:direction});await settled(p.log);g=await measure(GEOMETRY,p.log);
  }
  ensure(g?.hitTestable&&g.visibleWidth>0&&g.visibleHeight>0,`${where}: log is clipped or cannot receive wheel`);
  await p.cdp.send('Input.dispatchMouseEvent',{type:'mouseWheel',x:g.point.x/pointerScale,y:g.point.y/pointerScale,deltaX:0,deltaY:delta});await settled(p.log);return measure(LOG,p.log);}
 async function focusSelector(selector){const doc=await p.cdp.send('DOM.getDocument',{depth:0});const node=await p.cdp.send('DOM.querySelector',{nodeId:doc.root.nodeId,selector});ensure(node.nodeId,'Visible control missing: '+selector);await p.cdp.send('DOM.focus',{nodeId:node.nodeId});await settled(selector);}
 async function clickSend(question){
  if(!p.dom)await attach();const old=await qa.chat(p);ensure(!old.disabled&&old.input==='','Composer is disabled or contains unsent text');
  await focusSelector(p.input);await p.cdp.send('Input.insertText',{text:question});
  // Unlike qa.ask(), each measurement uses an actual visible Send click.
  const g=await measure(GEOMETRY,p.button);ensure(g?.hitTestable,'Send control cannot receive a real mouse click');
  const point={x:g.point.x/pointerScale,y:g.point.y/pointerScale,button:'left',clickCount:1};
  await p.cdp.send('Input.dispatchMouseEvent',{type:'mousePressed',...point});
  await p.cdp.send('Input.dispatchMouseEvent',{type:'mouseReleased',...point});
  return {...await qa.read(p,question),mouseInput:{cssPoint:g.point,protocolPoint:{x:point.x,y:point.y},pointerScale}};
 }
 async function lastReply(){return dom(`(s=>{const e=[...document.querySelectorAll(s+' .guide-assistant-message.ai')].at(-1);return e?{decision:e.dataset.decision,rendered:e.querySelector('.ga-msg-text')?.innerText||'',citations:[...e.querySelectorAll('.ga-msg-source')].map(n=>n.innerText),links:[...e.querySelectorAll('a[href]')].map(n=>n.href)}:null;})(${JSON.stringify(p.log)})`);}
 function checkOracle(answer,oracle){
  const expected=oracle?.expected;ensure(expected&&expected.decision==='answer','Caller must provide the frozen semantic oracle with expected answer');
  ensure(answer?.decision==='answer','Full answer was not returned');
  for(const value of expected.contains||[])ensure(narrow(answer.rendered).includes(narrow(value)),`Missing expected source phrase: ${value}`);
  const sources=expected.allSources||[expected.source];for(const source of sources)ensure(sourcePresent(source,answer.citations||[]),`Missing expected citation: ${source?.file} — ${source?.locator}`);
  for(const value of expected.notContains||[])ensure(!narrow(answer.rendered).includes(narrow(value)),`Forbidden phrase present: ${value}`);
 }
 async function direct(question,oracle,row,key){await clickSend(question);const a=await lastReply();row[key]=a;checkOracle(a,oracle);return a;}
 async function button(name){
  const r=await p.cdp.send('Runtime.evaluate',{expression:`Array.from(document.querySelectorAll('button')).find(e=>e.getClientRects().length>0&&(e.getAttribute('aria-label')||e.textContent.trim())===${JSON.stringify(name)})`,returnByValue:false});
  ensure(r.result?.objectId,'Visible button missing: '+name);const node=await p.cdp.send('DOM.requestNode',{objectId:r.result.objectId});await p.cdp.send('DOM.focus',{nodeId:node.nodeId});await tab.pressKey(null,'Return');
 }
 async function click(selector){ensure(await tab.playwright.locator(selector).isVisible(),'Original control is not visible: '+selector);await focusSelector(selector);await tab.pressKey(null,'Return');}
 async function setSize(pair){
  ensure(viewport,'Call load first');await viewport.set({width:pair[0],height:pair[1]});
  await p.cdp.send('Emulation.setDeviceMetricsOverride',{width:pair[0],height:pair[1],deviceScaleFactor:1,mobile:true});
  await pause(150);const observed=await dom('({width:innerWidth,height:innerHeight,devicePixelRatio})');
  ensure(observed.width===pair[0]&&observed.height===pair[1]&&observed.devicePixelRatio===1,'Exact CSS device viewport was not applied');
  return {requestedCss:pair,actualCss:observed,pointerScale,method:'current CUA CDP device metrics, mobile viewport semantics, DPR1; saved browser zoom unchanged; measured input conversion'};
 }
 async function reopenDefault(){
  switch(p.surface){
   case 'albion':await click('[data-target="briefing"]');await click('[data-target="missions"]');break;
   case 'ultima5':await click('#main-nav a[href="#quests"]');await click('#main-nav a[href="#counsel"]');break;
   case 'ultima6':await click('#close-seer-modal');await click(p.reopenSelector||'[data-seer-quest="act-i-liberating-the-shrines"][data-seer-section="compassion-britain"]');break;
   case 'ultima7':await click('#close-ai-modal');await click(p.reopenSelector||'.get-main-quest-hint[data-quest-index="0"]');break;
   case 'alqadim':await click('button[data-target="briefing"]');await click('button[data-target="genie"]');break;
   case 'alqadim-walkthrough':await click('button[data-target="briefing"]');await click('button[data-target="walkthrough"]');break;
   case 'starcraft':await click('#main-nav [href="#getting-started"]');await click('#main-nav [href="#ai-assistant"]');break;
   default:throw Error('Unsupported surface');
  }
 }
 async function record(type,key,fn){const row={type,surface:p.surface,...key,passed:false,problems:[]};try{Object.assign(row,await fn(row));row.passed=true;}catch(error){row.problems.push(String(error));}rows.push(row);return row;}
 return {
  async load(){
   ensure(SURFACES.includes(p.surface),'Unsupported surface');
   layout=JSON.parse(await tab.playwright.locator('#probe-layout').textContent());
   ensure(equal(layout.viewports,VIEWPORTS),'Frozen viewport fixture differs');
   const surface=layout.surfaces.find(s=>s.id===p.surface);ensure(surface,'Surface absent from fixture');
   ensure(layout.turns.length===8&&layout.turns.every(t=>typeof t.text==='string'),'Expected eight frozen questions');
   p.input=surface.input;p.button=surface.send;p.log=surface.log;
   viewport=await browser.capabilities.get('viewport');await attach();
   return {surface:p.surface,gameId:layout.gameId,dialogueId:layout.dialogueId,turns:layout.turns.map(t=>t.text),viewports:layout.viewports,selectors:surface};
  },
  async startSeed(){ensure(layout,'Call load first');await setSize(VIEWPORTS[0]);await noHelp();await button('Clear chat');await attach();seedTurns=[];seedPending=null;
   return {surface:p.surface,sent:0,total:layout.turns.length};},
  async seedNext(){ensure(layout,'Call load first');ensure(seedTurns.length<layout.turns.length,'Seed already complete');
   const question=layout.turns[seedTurns.length].text;let reply;
   if(seedPending){ensure(seedPending===question,'Pending seed question changed');const current=await qa.chat(p);
    reply=current.user===question&&current.input===''?await qa.read(p,question):await qa.ask(p,question);
   }else{seedPending=question;reply=await qa.ask(p,question);}
   seedTurns.push(reply);seedPending=null;
   return {surface:p.surface,sent:seedTurns.length,total:layout.turns.length,question,reply};},
  async seed(){await this.startSeed();while(seedTurns.length<layout.turns.length)await this.seedNext();
   return {surface:p.surface,sent:seedTurns.length,last:seedTurns.at(-1)};},
  async geometry(index){ensure(layout&&seedTurns.length===8&&Number.isInteger(index)&&index>=0&&index<VIEWPORTS.length,'Complete eight seed turns and choose a valid viewport index');const pair=VIEWPORTS[index];
   return record('geometry',{viewport:pair},async row=>{
    row.viewportObservation=await setSize(pair);await noHelp();
    // The original layout oracle first scrolls the composer into view. Use an
    // actual visible-control click here, letting the browser perform ordinary
    // focus scrolling; do not assign scrollTop or call scrollIntoView.
    const beforeReveal=await measure(GEOMETRY,p.input);
    if(!beforeReveal?.hitTestable||beforeReveal.visibleHeight<beforeReveal.height-2||beforeReveal.visibleWidth<beforeReveal.width-2){
     row.composerReveal={before:beforeReveal,action:'CUA DOM.focus on question input; browser performs normal focus scrolling'};
     await focusSelector(p.input);
    }
