export function summarizeUi63(rows){
 const required=[...SURFACES.flatMap(surface=>VIEWPORTS.map(viewport=>({type:'geometry',surface,viewport}))),
  ...SURFACES.flatMap(surface=>EXPANSION.map(viewport=>({type:'expansion',surface,viewport}))),
  ...SURFACES.map(surface=>({type:'lifecycle',surface}))];
 const matches=expected=>rows.filter(row=>row.type===expected.type&&row.surface===expected.surface
  && (!expected.viewport||equal(row.viewport,expected.viewport)));
 const missing=required.filter(expected=>matches(expected).length!==1);
 const failed=rows.filter(row=>!row.passed);
 return {expected:63,observations:rows.length,passed:rows.filter(row=>row.passed).length,missingOrDuplicate:missing,failed,complete:rows.length===63&&!missing.length&&!failed.length};
}

